import React from 'react';
import { Link } from 'react-router-dom';
import '../assets/styles.css';
import '../assets/home-dark.css';
import '../assets/server-theme.css';

import logoNuevo from '../assets/img/logonuevo.png';
import UserMenu from '../components/UserMenu.jsx';
import {
  TICKET_CATEGORIES,
  TicketThread,
  categoryMeta,
  statusMeta,
  formatDate,
} from './Profile.jsx';

const STATUS_FILTERS = [
  { id: '', label: 'Todos' },
  { id: 'open', label: 'Abiertos' },
  { id: 'answered', label: 'Respondidos' },
  { id: 'closed', label: 'Cerrados' },
];

async function readJsonSafe(response) {
  try {
    return await response.json();
  } catch (e) {
    return null;
  }
}

export default function Admin() {
  const [user, setUser] = React.useState(undefined);
  const [tab, setTab] = React.useState('tickets'); // tickets | users

  // tickets
  const [tickets, setTickets] = React.useState([]);
  const [counts, setCounts] = React.useState({ open: 0, answered: 0, closed: 0 });
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState('');
  const [statusFilter, setStatusFilter] = React.useState('');
  const [categoryFilter, setCategoryFilter] = React.useState('');
  const [search, setSearch] = React.useState('');
  const [selectedId, setSelectedId] = React.useState(null);
  const [deleteError, setDeleteError] = React.useState('');

  // usuarios
  const [users, setUsers] = React.useState([]);
  const [usersLoading, setUsersLoading] = React.useState(false);

  React.useEffect(() => {
    document.body.classList.add('has-video-bg');
    return () => document.body.classList.remove('has-video-bg');
  }, []);

  React.useEffect(() => {
    let active = true;
    fetch('/api/user', { credentials: 'include' })
      .then((response) => (response.ok ? response.json() : null))
      .then((data) => {
        if (active) setUser(data && data.steamid ? data : null);
      })
      .catch(() => {
        if (active) setUser(null);
      });
    return () => {
      active = false;
    };
  }, []);

  const isAdmin = Boolean(user && user.isAdmin);

  const loadTickets = React.useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const params = new URLSearchParams();
      if (statusFilter) params.set('status', statusFilter);
      if (categoryFilter) params.set('category', categoryFilter);
      if (search.trim()) params.set('q', search.trim());
      const response = await fetch(`/api/admin/tickets?${params.toString()}`, { credentials: 'include' });
      const json = await readJsonSafe(response);
      if (!response.ok) {
        setError(json?.error || 'No se pudieron cargar los tickets.');
        setTickets([]);
        return;
      }
      setTickets(Array.isArray(json?.tickets) ? json.tickets : []);
      if (json?.counts) setCounts(json.counts);
    } catch (e) {
      setError('Error de conexión.');
      setTickets([]);
    } finally {
      setLoading(false);
    }
  }, [statusFilter, categoryFilter, search]);

  React.useEffect(() => {
    if (!isAdmin) return;
    loadTickets();
  }, [isAdmin, loadTickets]);

  React.useEffect(() => {
    if (!isAdmin || tab !== 'users') return undefined;
    let active = true;
    setUsersLoading(true);
    fetch('/api/admin/users', { credentials: 'include' })
      .then((response) => (response.ok ? response.json() : []))
      .then((data) => {
        if (active) setUsers(Array.isArray(data) ? data : []);
      })
      .catch(() => {
        if (active) setUsers([]);
      })
      .finally(() => {
        if (active) setUsersLoading(false);
      });
    return () => {
      active = false;
    };
  }, [isAdmin, tab]);

  const deleteTicket = async (id) => {
    if (!window.confirm(`¿Eliminar definitivamente el ticket #${id} y toda su conversación?`)) {
      return;
    }
    setDeleteError('');
    try {
      const response = await fetch(`/api/admin/tickets/${id}`, {
        method: 'DELETE',
        credentials: 'include',
      });
      const json = await readJsonSafe(response);
      if (!response.ok) {
        setDeleteError(json?.error || 'No se pudo eliminar el ticket.');
        return;
      }
      if (selectedId === id) setSelectedId(null);
      loadTickets();
    } catch (e) {
      setDeleteError('Error de conexión.');
    }
  };

  return (
    <div className="rw-page">
      <header className="rw-nav">
        <Link to="/" className="rw-nav-brand">
          <img src={logoNuevo} alt="Rustaco" />
          <span>
            Rust<em>aco</em>
          </span>
        </Link>

        <nav className="rw-nav-links" aria-label="Navegación">
          <Link to="/" className="rw-nav-link">Inicio</Link>
          <Link to="/rules" className="rw-nav-link">Reglas</Link>
          <Link to="/maps" className="rw-nav-link">Maps</Link>
          <Link to="/events" className="rw-nav-link">Leaderboard</Link>
          <span className="rw-nav-link" style={{ color: '#fff' }} aria-current="page">Admin</span>
        </nav>

        <div className="rw-nav-right">
          <UserMenu />
        </div>
      </header>

      <main className="rw-lb-main">
        {user === undefined && (
          <div className="rw-lb-state" style={{ maxWidth: 560 }}>
            <span className="rw-spinner" />
            <div>Verificando acceso...</div>
          </div>
        )}

        {user === null && (
          <div className="rw-login-card">
            <i className="bi bi-shield-lock rw-login-icon" />
            <h1>Acceso restringido</h1>
            <p>Inicia sesión con una cuenta de administrador para acceder al panel.</p>
            <a className="rw-btn rw-btn--primary" href="/auth/steam">
              <i className="bi bi-steam" /> Iniciar sesión con Steam
            </a>
          </div>
        )}

        {user && !isAdmin && (
          <div className="rw-login-card">
            <i className="bi bi-shield-x rw-login-icon" />
            <h1>Sin permisos</h1>
            <p>
              Tu cuenta <b>{user.name}</b> no tiene permisos de administrador.
              Si crees que es un error, contacta al staff por Discord.
            </p>
            <Link className="rw-btn rw-btn--ghost" to="/profile">
              <i className="bi bi-person" /> Ir a mi perfil
            </Link>
          </div>
        )}

        {isAdmin && (
          <div className="rw-profile">
            <div className="rw-lb-head" style={{ marginBottom: '1.6rem' }}>
              <span className="rw-section-kicker">Panel administrativo</span>
              <h1>Gestión de tickets</h1>
            </div>

            {/* ── Contadores ── */}
            <section className="rw-admin-stats">
              <div className="rw-admin-stat rw-admin-stat--open">
                <strong>{counts.open}</strong>
                <span>Abiertos</span>
              </div>
              <div className="rw-admin-stat rw-admin-stat--answered">
                <strong>{counts.answered}</strong>
                <span>Respondidos</span>
              </div>
              <div className="rw-admin-stat rw-admin-stat--closed">
                <strong>{counts.closed}</strong>
                <span>Cerrados</span>
              </div>
              <div className="rw-admin-stat">
                <strong>{counts.open + counts.answered + counts.closed}</strong>
                <span>Total</span>
              </div>
            </section>

            {/* ── Tabs panel ── */}
            <div className="rw-lb-tabs" style={{ marginBottom: '1rem', alignSelf: 'flex-start' }}>
              <button
                type="button"
                className={`rw-lb-tab ${tab === 'tickets' ? 'rw-lb-tab--active' : ''}`}
                onClick={() => setTab('tickets')}
              >
                <i className="bi bi-ticket-detailed" /> Tickets
              </button>
              <button
                type="button"
                className={`rw-lb-tab ${tab === 'users' ? 'rw-lb-tab--active' : ''}`}
                onClick={() => setTab('users')}
              >
                <i className="bi bi-people" /> Usuarios
              </button>
            </div>

            {tab === 'tickets' && (
              <section className="rw-panel">
                {/* filtros */}
                <div className="rw-admin-filters">
                  <div className="rw-lb-tabs">
                    {STATUS_FILTERS.map((filter) => (
                      <button
                        key={filter.id || 'all'}
                        type="button"
                        className={`rw-lb-tab ${statusFilter === filter.id ? 'rw-lb-tab--active' : ''}`}
                        onClick={() => setStatusFilter(filter.id)}
                      >
                        {filter.label}
                      </button>
                    ))}
                  </div>
                  <select
                    className="rw-input rw-input--inline"
                    value={categoryFilter}
                    onChange={(event) => setCategoryFilter(event.target.value)}
                    aria-label="Filtrar por categoría"
                  >
                    <option value="">Todas las categorías</option>
                    {TICKET_CATEGORIES.map((cat) => (
                      <option key={cat.id} value={cat.id}>{cat.label}</option>
                    ))}
                  </select>
                  <div className="rw-lb-search">
                    <i className="bi bi-search" aria-hidden="true" />
                    <input
                      type="search"
                      value={search}
                      onChange={(event) => setSearch(event.target.value)}
                      placeholder="Asunto, nombre o SteamID..."
                      aria-label="Buscar tickets"
                    />
                  </div>
                </div>

                {deleteError && (
                  <div className="rw-form-error">
                    <i className="bi bi-exclamation-circle" /> {deleteError}
                  </div>
                )}

                {loading && (
                  <div className="rw-lb-state" style={{ border: 'none' }}>
                    <span className="rw-spinner" />
                    <div>Cargando tickets...</div>
                  </div>
                )}

                {!loading && error && (
                  <div className="rw-lb-state rw-lb-state--error">{error}</div>
                )}

                {!loading && !error && tickets.length === 0 && (
                  <div className="rw-lb-state" style={{ border: 'none' }}>
                    <i className="bi bi-inbox" style={{ fontSize: '1.6rem', display: 'block', marginBottom: 8 }} />
                    No hay tickets con estos filtros.
                  </div>
                )}

                {!loading && !error && tickets.length > 0 && (
                  <div className="rw-ticket-list">
                    {tickets.map((ticket) => {
                      const status = statusMeta(ticket.Status);
                      const cat = categoryMeta(ticket.Category);
                      return (
                        <div key={ticket.Id} className="rw-ticket-item rw-ticket-item--admin">
                          <button
                            type="button"
                            className="rw-ticket-item-open"
                            onClick={() => setSelectedId(ticket.Id)}
                          >
                            <span className="rw-ticket-item-icon">
                              {ticket.Avatar ? <img src={ticket.Avatar} alt="" /> : <i className={`bi ${cat.icon}`} />}
                            </span>
                            <span className="rw-ticket-item-main">
                              <strong>
                                <span className="rw-thread-id">#{ticket.Id}</span> {ticket.Subject}
                              </strong>
                              <span className="rw-ticket-item-sub">
                                {ticket.UserName} ({ticket.SteamId}) · {cat.label} · {Number(ticket.Messages) || 0} msg · {formatDate(ticket.UpdatedAt)}
                              </span>
                            </span>
                            <span className={`rw-badge ${status.className}`}>
                              <i className={`bi ${status.icon}`} /> {status.label}
                            </span>
                          </button>
                          <button
                            type="button"
                            className="rw-icon-btn rw-icon-btn--danger"
                            title={`Eliminar ticket #${ticket.Id}`}
                            onClick={() => deleteTicket(ticket.Id)}
                          >
                            <i className="bi bi-trash3" />
                          </button>
                        </div>
                      );
                    })}
                  </div>
                )}
              </section>
            )}

            {tab === 'users' && (
              <section className="rw-panel">
                <div className="rw-panel-head">
                  <h2>
                    <i className="bi bi-people" /> Usuarios autenticados
                  </h2>
                </div>
                {usersLoading ? (
                  <div className="rw-lb-state" style={{ border: 'none' }}>
                    <span className="rw-spinner" />
                    <div>Cargando usuarios...</div>
                  </div>
                ) : users.length === 0 ? (
                  <div className="rw-lb-state" style={{ border: 'none' }}>
                    Sin usuarios registrados desde el último reinicio del servidor.
                  </div>
                ) : (
                  <div className="rw-ticket-list">
                    {users.map((entry) => (
                      <div key={entry.steamid} className="rw-ticket-item" style={{ cursor: 'default' }}>
                        <span className="rw-ticket-item-icon">
                          {entry.avatar ? <img src={entry.avatar} alt="" /> : <i className="bi bi-person-circle" />}
                        </span>
                        <span className="rw-ticket-item-main">
                          <strong>{entry.name}</strong>
                          <span className="rw-ticket-item-sub">
                            {entry.steamid} · Último login: {formatDate(entry.lastLogin)}
                          </span>
                        </span>
                      </div>
                    ))}
                  </div>
                )}
              </section>
            )}
          </div>
        )}
      </main>

      {/* ── Modal detalle de ticket ── */}
      {isAdmin && selectedId !== null && (
        <div
          role="presentation"
          onClick={() => setSelectedId(null)}
          className="rw-modal-overlay"
        >
          <div
            role="dialog"
            aria-modal="true"
            onClick={(event) => event.stopPropagation()}
            className="rw-modal"
          >
            <div className="rw-modal-header">
              <h2 className="rw-modal-title">
                <i className="bi bi-ticket-detailed" aria-hidden="true" />
                Ticket #{selectedId}
              </h2>
              <button
                type="button"
                onClick={() => setSelectedId(null)}
                className="rw-modal-close"
                aria-label="Cerrar"
              >
                <i className="bi bi-x-lg" aria-hidden="true" />
              </button>
            </div>
            <div className="rw-modal-body">
              <TicketThread
                ticketId={selectedId}
                currentUser={user}
                onChanged={loadTickets}
                allowAdminActions
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
